# Even-ring rule on the correct pairs: verify pair 2 & 8, and also pair3 with proper seeds.
from collections import Counter
def f(i):
    h=len(i); w=len(i[0])
    bg=Counter(x for row in i for x in row).most_common(1)[0][0]
    seeds=[(r,c,i[r][c]) for r in range(h) for c in range(w) if i[r][c]!=bg]
    out=[[bg]*w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            dists={col:max(abs(r-se),abs(c-sc)) for (se,sc,col) in seeds}
            mn=min(dists.values())
            if mn%2==0:
                winners=[col for col,k in dists.items() if k==mn]
                out[r][c]=winners[0] if len(winners)==1 else None
    return out
for n in [2,3,4,5,6,7,8]:
